// =====================================================================
// LabelBridge · Construye el trabajo de impresión a partir del pedido
// =====================================================================
// Entrada: el pedido (webhook orders/paid, formato REST) + "canal" y
// "printer" del nodo Configuración. Salida: el trabajo (Job) que se
// publica en MQTT tal cual.

const o = $json;

const canal = String(o.canal ?? '').trim();
if (!/^[a-z0-9-]+$/.test(canal)) {
  throw new Error(`Canal inválido "${canal}" en "Configuración": usa solo minúsculas, números y guiones (el mismo canal que en la app).`);
}

// Solo los datos que necesita la etiqueta: se minimizan los datos del cliente
// que salen de Shopify (nada de email, teléfono del cliente, pagos, etc.).
const order = {
  id: o.id,
  name: o.name,
  order_number: o.order_number,
  created_at: o.created_at,
  shipping_address: o.shipping_address ?? null,
  shipping_lines: (o.shipping_lines ?? []).map((l) => ({ title: l.title })),
  line_items: (o.line_items ?? []).map((li) => ({
    quantity: li.quantity,
    name: li.name,
    title: li.title,
    variant_title: li.variant_title,
    sku: li.sku,
  })),
  note: o.note ?? null,
  total_price: o.total_price,
  currency: o.currency,
};
// La dirección de facturación solo se envía si el pedido no tiene dirección de envío.
if (!o.shipping_address && o.billing_address) {
  order.billing_address = o.billing_address;
}

// ---------------------------------------------------------------------
// OPCIÓN A (por defecto) · format "order": la app dibuja la etiqueta con la
// dirección y los artículos del pedido.
// ---------------------------------------------------------------------
const job = {
  id: `pedido-${o.id}`,                      // único: la app lo usa para no imprimir dos veces
  title: `Pedido ${o.name}`,                  // texto del historial de la app
  ...(o.printer ? { printer: o.printer } : {}), // sin printer → impresora predeterminada de la app
  copies: 1,
  format: 'order',
  order,
  meta: { order_id: String(o.id), order_name: o.name },
};

// ---------------------------------------------------------------------
// OPCIÓN B · imprimir una etiqueta que ya existe como archivo (PDF/ZPL/PNG)
// Si tu paquetería u otra app te da la URL de la etiqueta, sustituye el
// objeto "job" de arriba por algo así:
//
// const job = {
//   id: `etiqueta-${o.id}`,
//   title: `Etiqueta ${o.name}`,
//   printer: o.printer,
//   copies: 1,
//   format: 'pdf',                                  // 'pdf' | 'zpl' | 'image' | 'auto'
//   url: 'https://ejemplo.com/etiquetas/123.pdf',   // la app descarga el archivo
//   // headers: { Authorization: 'Bearer XXX' },    // opcional, si la descarga lo requiere
//   meta: { order_id: String(o.id), order_name: o.name },
// };
//
// Cada trabajo lleva UNA sola fuente de datos: "order", "url",
// "content" (texto, p. ej. ZPL ^XA...^XZ) o "content_base64".
// ---------------------------------------------------------------------

return { json: job };
